"""Shared navigation is added to published copies, keeping release snapshots immutable."""
import html,json
from pathlib import Path
NAV_JS = r'''(()=>{'use strict';if(new URLSearchParams(location.search).get('embedded')==='1'){const archive=document.querySelector('#archive');if(archive)archive.target='_top';return;}
const script=document.currentScript,base=new URL('.',script.src),current=script.dataset.version,light=document.documentElement?.dataset?.theme==='light'||/^1\./.test(current);
const host=document.createElement('div');host.id='immune-version-navigation';host.style.cssText='position:fixed;inset:0 0 auto 0;z-index:2147483000;--bar-bg:'+(light?'#f7faf4':'#111b2b')+';--bar-ink:'+(light?'#27524a':'#efe5ce')+';--bar-line:'+(light?'#b9d1c2':'#3f5964')+';--bar-input:'+(light?'#ffffff':'#23374c')+';--bar-link:'+(light?'#246f61':'#83e0c8')+';--bar-shadow:'+(light?'#d3e3d6':'#080d17');
const shadow=host.attachShadow({mode:'open'});shadow.innerHTML=`<style>:host{font:13px/1.4 -apple-system,sans-serif;color:var(--bar-ink)}*{box-sizing:border-box}.bar{height:46px;background:var(--bar-bg);border-bottom:2px solid var(--bar-line);display:flex;align-items:center;justify-content:center;gap:14px;padding:5px 12px;box-shadow:0 3px 0 var(--bar-shadow)}label{font-weight:700;white-space:nowrap}select{font:inherit;max-width:300px;background:var(--bar-input);color:var(--bar-ink);border:1px solid var(--bar-line);padding:5px 7px}a{color:var(--bar-link);text-decoration:none;white-space:nowrap}a:focus-visible,select:focus-visible{outline:2px solid #f0cb7a;outline-offset:2px}@media(max-width:600px){.bar{gap:9px;font-size:11px}select{max-width:145px}label{display:none}}</style><nav class="bar" aria-label="遊戲版本切換"><label for="version">切換版本</label><select id="version" aria-label="選擇遊戲版本"><option>v${current}</option></select><a id="latest">回到新版 ↗</a><a id="archive">版本檔案室</a></nav>`;
document.body.prepend(host);document.body.style.paddingTop='46px';shadow.querySelector('#archive').href=new URL('index.html',base).href;shadow.querySelector('#latest').href=new URL('../index.html',base).href;
fetch(new URL('manifest.json',base),{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('version list unavailable');return r.json()}).then(records=>{shadow.querySelector('#latest').href=new URL('play.html?version='+encodeURIComponent(records[records.length-1].version)+'&catalog='+encodeURIComponent(records[records.length-1].version),base).href;const select=shadow.querySelector('#version');select.replaceChildren(...records.slice().reverse().map(r=>{const o=document.createElement('option');o.value=r.version;o.textContent='v'+r.version+' · '+r.title;o.selected=r.version===current;return o}));select.addEventListener('change',()=>{location.href=new URL('play.html?version='+encodeURIComponent(select.value)+'&catalog='+encodeURIComponent(records[records.length-1].version),base).href})}).catch(()=>{shadow.querySelector('#version').disabled=true});})();'''
STYLE='''*{box-sizing:border-box}body{margin:0;background:#edf3ee;color:#21443e;font:16px/1.7 -apple-system,sans-serif}main{max-width:980px;margin:auto;padding:48px 24px}h1{font-size:32px}p,small{color:#60786d}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}article{padding:24px;border:2px solid #bfd1c2;background:#fbfcf8;box-shadow:5px 5px 0 #d1e1d4}h2{font-size:19px}.version{color:#277b65;font-weight:800}a{display:block;color:#277b65;text-decoration:none;font-weight:bold;margin-top:18px}nav a{display:inline-block;margin:0}'''
def write_pages(folder,records):
    folder=Path(folder)
    cards='\n'.join(f'<article><div class="version">v{html.escape(x["version"])}</div><h2>{html.escape(x["title"])}</h2><p>{html.escape(x["notes"])}</p><small>{html.escape(x["date"])} · 獨立版本備份</small><a href="play.html?version={html.escape(x["version"])}&amp;catalog={html.escape(records[-1]["version"])}">玩這個版本 →</a></article>' for x in reversed(records))
    index='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>免疫前線｜版本檔案室</title><style>'''+STYLE+'''</style><main><nav><a href="../index.html" id="latest">← 回到新版</a></nav><h1>版本檔案室</h1><p>選一版開始遊玩；遊戲上方都有版本選單，可以直接換回新版。切換版本會重新開始該版遊戲。</p><div class="grid">'''+cards+'''</div></main><script>if(location.protocol==='file:')document.querySelector('#latest').href='../immune-frontline.html';</script></html>'''
    index=index.replace('href="../index.html" id="latest"', 'href="play.html?version='+records[-1]['version']+'&amp;catalog='+records[-1]['version']+'" id="latest"')
    folder.joinpath('index.html').write_text(index)
    data=json.dumps(records,ensure_ascii=False).replace('</','<\\/')
    player='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>免疫前線｜切換版本</title><style>*{box-sizing:border-box}html,body{margin:0;height:100%;background:#f1f6ef;color:#21443e;font:13px -apple-system,sans-serif}nav{height:54px;display:flex;align-items:center;justify-content:center;gap:14px;padding:6px 10px;border-bottom:2px solid #c1d4c5}select{max-width:360px;font:inherit;background:#ffffff;color:#285549;border:1px solid #8dbca3;padding:7px}a{color:#247963;text-decoration:none;white-space:nowrap}iframe{width:100%;height:calc(100% - 54px);border:0;display:block}a:focus-visible,select:focus-visible{outline:2px solid #f0cb7a;outline-offset:2px}@media(max-width:600px){nav{gap:9px;font-size:11px}select{max-width:155px}label{display:none}}</style></head><body><nav aria-label="遊戲版本切換"><label for="version">切換版本</label><select id="version" aria-label="選擇遊戲版本"></select><a id="latest" href="../index.html">回到新版 ↗</a><a href="index.html">版本檔案室</a></nav><iframe id="game" title="免疫前線遊戲" allow="fullscreen"></iframe><script>
const records='''+data+''';const select=document.querySelector('#version'),frame=document.querySelector('#game');for(const r of records.slice().reverse()){const o=document.createElement('option');o.value=r.version;o.textContent='v'+r.version+' · '+r.title;select.append(o)}const requested=new URLSearchParams(location.search).get('version');select.value=records.some(r=>r.version===requested)?requested:records[records.length-1].version;
function load(){const record=records.find(r=>r.version===select.value);frame.src=record.file+'?embedded=1';document.title='免疫前線 v'+record.version;const url=new URL(location.href);url.searchParams.set('version',record.version);try{history.replaceState(null,'',url)}catch{} }select.onchange=load;document.querySelector('#latest').onclick=(event)=>{event.preventDefault();select.value=records[records.length-1].version;load()};if(location.protocol==='file:')document.querySelector('#latest').href='../immune-frontline.html';load();
</script></body></html>'''
    folder.joinpath('play.html').write_text(player)
    folder.joinpath('navigation.js').write_text(NAV_JS+'\n')

def decorate_game(content,version,script_path):
    insertion='<script data-version="'+html.escape(version,quote=True)+'" src="'+html.escape(script_path,quote=True)+'"></script>'
    return content.replace('</body>',insertion+'</body>')
